import type { Role } from '../app'
import type {
    AttachmentVariable,
    BreakVariable,
    CheckboxVariable,
    ContainerEndVariable,
    ContainerSplitVariable,
    ContainerStartVariable,
    CustomVariable,
    CustomWithLabelVariable,
    DateTimeVariable,
    DateVariable,
    DurationVariable,
    EmailVariable,
    HtmlVariable,
    IpAddressVariable,
    LabelVariable,
    ListCollectorVariable,
    LookupMultipleChoiceVariable,
    LookupSelectBoxVariable,
    MaskedVariable,
    MultiLineTextVariable,
    MultipleChoiceVariable,
    NumericScaleVariable,
    ReferenceVariable,
    RequestedForVariable,
    RichTextLabelVariable,
    SelectBoxVariable,
    SingleLineTextVariable,
    UIPageVariable,
    UrlVariable,
    WideSingleLineTextVariable,
    YesNoVariable,
} from '../service-catalog/types/Variables/index'

// variables/BaseVariable.ts
const type = '__type__'
export type Typed<Type, T = object> = {
    [K in keyof (T & { readonly [type]?: Type })]: (T & { readonly [type]?: Type })[K]
}
export type PricingDetail = {
    amount: number
    currencyType: string
    field: string
}

/**
 * Base variable type definition with generic type parameter
 * This type doesn't include interactive properties (mandatory, hidden, readOnly)
 */
export type BaseVariableConfig<Type = unknown, Default extends Type = Type> = Typed<
    Type,
    {
        question: string
        /** Order in which the variable appears */
        order?: number
        active?: boolean
        disableInitialSlotFill?: boolean
        conversationalLabel?: string
        tooltip?: string
        exampleText?: string
        showHelp?: boolean
        helpTag?: string
        helpText?: string
        instructions?: string
        /** Width of the variable */
        width?: 25 | 50 | 75 | 100
        /** Attributes of the variable */
        attributes?: string
        readRoles?: (string | Role)[]
        writeRoles?: (string | Role)[]
        createRoles?: (string | Role)[]
        defaultValue?: Default | string
        visibleBundle?: boolean
        /** Indicates whether the variable is visible in guides */
        visibleGuide?: boolean
        /** Indicates whether the variable is visible when standalone */
        visibleStandalone?: boolean
        /** Indicates whether the variable is visible in summaries */
        visibleSummary?: boolean
        /** Remove from Conversational Interfaces */
        removeFromConversationalInterfaces?: boolean
        /** Pricing details */
        pricingDetails?: PricingDetail[]
        /** Always expand */
        alwaysExpand?: boolean
        /** Description */
        description?: string
        /** Global */
        global?: boolean
        /** Layout style for the container */
        layout?: 'normal' | '2across' | '2down'
        /** Delivery plan */
        deliveryPlan?: string
        /** Visibility */
        visibility?: 'Always' | 'Bundle' | 'Standalone'
        /** Category */
        category?: string
        /** Pricing implications */
        pricingImplications?: boolean
        /** Use dynamic default */
        useDynamicDefault?: boolean
        /** Unique value */
        unique?: boolean
        /** Dot walk path for dynamic default value */
        dotWalkPath?: string
        /** Dependent question for dynamic default value */
        dependentQuestion?: string
        /** Read script */
        readScript?: string
        /** Post insert script */
        postInsertScript?: string
    } & {
        /** Map to field */
        mapToField?: boolean
        /** Field to map (required when mapToField is true) */
        field?: string
    }
>

/**
 * Variable type definition with generic type parameter
 * Includes interactive properties (mandatory, hidden, readOnly)
 * Note: mandatory cannot be true if hidden or readOnly is true, and vice versa
 */
export type VariableConfig<Type = unknown, Default extends Type = Type> = BaseVariableConfig<Type, Default> & {
    /** Indicates whether the field must contain a value. Cannot be true when hidden or readOnly is true. */
    mandatory?: boolean
    /** Indicates whether the field is read-only. Cannot be true when mandatory is true. */
    readOnly?: boolean
    /** Indicates whether the field is hidden. Cannot be true when mandatory is true. */
    hidden?: boolean
}

/**
 * Type representing all possible variable types that can be used in a catalog item
 */
type AnyVariable =
    | ReturnType<typeof SingleLineTextVariable>
    | ReturnType<typeof MultiLineTextVariable>
    | ReturnType<typeof ReferenceVariable>
    | ReturnType<typeof YesNoVariable>
    | ReturnType<typeof SelectBoxVariable>
    | ReturnType<typeof DateVariable>
    | ReturnType<typeof DateTimeVariable>
    | ReturnType<typeof HtmlVariable>
    | ReturnType<typeof LabelVariable>
    | ReturnType<typeof BreakVariable>
    | ReturnType<typeof CustomVariable>
    | ReturnType<typeof UIPageVariable>
    | ReturnType<typeof ContainerStartVariable>
    | ReturnType<typeof ContainerSplitVariable>
    | ReturnType<typeof WideSingleLineTextVariable>
    | ReturnType<typeof CustomWithLabelVariable>
    | ReturnType<typeof MaskedVariable>
    | ReturnType<typeof EmailVariable>
    | ReturnType<typeof UrlVariable>
    | ReturnType<typeof IpAddressVariable>
    | ReturnType<typeof DurationVariable>
    | ReturnType<typeof RequestedForVariable>
    | ReturnType<typeof RichTextLabelVariable>
    | ReturnType<typeof AttachmentVariable>
    | ReturnType<typeof MultipleChoiceVariable>
    | ReturnType<typeof ContainerEndVariable>
    | ReturnType<typeof ListCollectorVariable>
    | ReturnType<typeof LookupMultipleChoiceVariable>
    | ReturnType<typeof LookupSelectBoxVariable>
    | ReturnType<typeof NumericScaleVariable>
    | ReturnType<typeof CheckboxVariable>

type NonEmpty<T extends globalThis.Record<string, unknown>> = keyof T extends never ? never : T

export type VariableTypes = NonEmpty<globalThis.Record<string, AnyVariable>>

/**
 * Type representing a variable reference that can be used in catalog scripts and policies.
 * Accepts either a string name or a properly typed variable reference.
 */
export type VariableReference = AnyVariable
